// ============================================================================
// REPO PATH: api/_lib/mb-bip-extra.js
// ============================================================================
// multicalci.com — STEP 32: hand-maintained binary interaction parameters that
// fill gaps in (or deliberately replace) the generated ChemSep tables in
// mb-bip.js. mb-bip.js is regenerated by scripts/build-compdb.py and must not
// be edited by hand; calibrated values live HERE, each with its source.
//
// Precedence when a package is built (mb-thermo.js createPackage):
//   flowsheet user override (Methods → binary data)  >  this file  >  ChemSep
//
// PR    'a|b' (keys sorted alphabetically) → { kij, source }
//       used by Peng–Robinson and SRK (and an EOS vapour under γ methods)
// NRTL  'i|j' (directional, as in mb-bip.js) → { b, alpha, source }
//       τ_ij = b_ij / T. Give both directions of a pair.
//
// What is NOT here, and why:
//   · gas–water pairs (H2, N2, CH4, CO, Ar, O2, C2H6, CO2, H2S, …): their
//     solubility in water is set by the free-water option of the cubic EOS
//     from IAPWS G7-04 Henry constants (mb-thermo.js), which a constant k_ij
//     cannot reproduce;
//   · gas–ammonia pairs (H2–NH3, CH4–NH3, CO–NH3): no verified data set has
//     been adopted yet. They stay at k_ij = 0 and the engine says so in the
//     run warnings. Fit them to measured ammonia-separator analyses (T, P,
//     vapour and liquid composition) and add them below with the source.
//
// Plain ES module, no dependencies. (c) multicalci.com
// ============================================================================

export const BIP_EXTRA_VERSION = 'mb-bip-extra 1.0.0';

export const PR = {
  // 'H2|NH3': { kij: 0, source: 'fitted to <plant> separator analyses, <date>' },
};

export const NRTL = {
  // 'H2O|NH3': { b: 0, alpha: 0.3, source: '…' },
  // 'NH3|H2O': { b: 0, alpha: 0.3, source: '…' },
};

/**
 * Merge the entries above into the generated tables (in place) and return the
 * list of pairs taken from this file, so property reports can name the source.
 * @param {{PR:object, NRTL:object}} bip the mb-bip.js default export
 * @returns {{PR:Object<string,string>, NRTL:Object<string,string>}} pair → source
 */
export function applyExtra(bip) {
  const used = { PR: {}, NRTL: {} };
  for (const [pair, e] of Object.entries(PR)) {
    if (!e || typeof e.kij !== 'number' || !isFinite(e.kij)) continue;
    bip.PR[pair] = e.kij;
    used.PR[pair] = e.source || 'mb-bip-extra.js';
  }
  for (const [pair, e] of Object.entries(NRTL)) {
    if (!e || typeof e.b !== 'number' || !isFinite(e.b)) continue;
    bip.NRTL[pair] = [e.b, typeof e.alpha === 'number' ? e.alpha : 0.3];
    used.NRTL[pair] = e.source || 'mb-bip-extra.js';
  }
  return used;
}

export default { BIP_EXTRA_VERSION, PR, NRTL, applyExtra };
